<script setup>import AppShell from'../../Layouts/AppShell.vue';import PageHeader from'../../Components/PageHeader.vue';import UiButton from'../../Components/UiButton.vue';import UiAlert from'../../Components/UiAlert.vue';import{Head,Link,useForm}from'@inertiajs/vue3';const p=defineProps({section:String,user:Object,team:Array});const names=p.user.name.split(' '),profile=useForm({first_name:names.shift()||'',last_name:names.join(' '),email:p.user.email,phone:p.user.phone,password:'',password_confirmation:''}),branding=useForm({studio_name:p.user.meta?.studio_name||'',studio_tagline:p.user.meta?.studio_tagline||'',brand_color:p.user.meta?.brand_color||'#4f46e5'}),watermark=useForm({watermark_text:p.user.meta?.watermark_text||'',watermark_position:p.user.meta?.watermark_position||'bottom-right',watermark_opacity:p.user.meta?.watermark_opacity||70});const nav=[['profile','Profile'],['branding','Branding'],['watermark','Watermark'],['team','Team'],['subscription','Plan & billing']];</script><template><AppShell><Head title="Settings"/><div class="lp-page"><PageHeader eyebrow="Account" title="Settings" description="Manage your LensPic account and studio delivery preferences."/><div class="mt-8 grid gap-6 lg:grid-cols-[220px_1fr]"><nav class="lp-card h-fit p-2" aria-label="Settings sections"><Link v-for="n in nav" :key="n[0]" :href="`/settings/${n[0]==='subscription'?'subscription':n[0]}`" :class="['block rounded-xl px-4 py-3 text-sm font-semibold',section===n[0]?'bg-indigo/10 text-indigo':'text-slate-600 hover:bg-slate-50']">{{n[1]}}</Link></nav><UiCard><form v-if="section==='profile'" class="space-y-5" @submit.prevent="profile.post('/settings/profile')"><h2 class="text-xl font-bold">Profile and security</h2><div class="grid gap-4 md:grid-cols-2"><label class="lp-label">First name<input v-model="profile.first_name" class="field mt-2" required></label><label class="lp-label">Last name<input v-model="profile.last_name" class="field mt-2"></label></div><label class="lp-label">Email<input v-model="profile.email" type="email" class="field mt-2" required></label><label class="lp-label">Phone<input v-model="profile.phone" class="field mt-2"></label><div class="grid gap-4 md:grid-cols-2"><label class="lp-label">New password<input v-model="profile.password" type="password" class="field mt-2"></label><label class="lp-label">Confirm password<input v-model="profile.password_confirmation" type="password" class="field mt-2"></label></div><UiAlert v-if="Object.keys(profile.errors).length" tone="error">Review the highlighted profile information.</UiAlert><UiButton type="submit" :loading="profile.processing">Save profile</UiButton></form><form v-else-if="section==='branding'" class="space-y-5" @submit.prevent="branding.post('/settings/branding')"><h2 class="text-xl font-bold">Studio branding</h2><label class="lp-label">Studio name<input v-model="branding.studio_name" class="field mt-2"></label><label class="lp-label">Tagline<input v-model="branding.studio_tagline" class="field mt-2"></label><label class="lp-label">Brand colour<input v-model="branding.brand_color" type="color" class="field mt-2 h-14 p-2"></label><UiButton type="submit" :loading="branding.processing">Save branding</UiButton></form><form v-else-if="section==='watermark'" class="space-y-5" @submit.prevent="watermark.post('/settings/watermark')"><h2 class="text-xl font-bold">Watermark</h2><label class="lp-label">Watermark text<input v-model="watermark.watermark_text" class="field mt-2"></label><label class="lp-label">Position<select v-model="watermark.watermark_position" class="field mt-2"><option value="bottom-right">Bottom right</option><option value="bottom-left">Bottom left</option><option value="center">Center</option></select></label><label class="lp-label">Opacity: {{watermark.watermark_opacity}}%<input v-model="watermark.watermark_opacity" type="range" min="10" max="100" class="mt-3 w-full accent-indigo"></label><UiButton type="submit" :loading="watermark.processing">Save watermark</UiButton></form><div v-else-if="section==='team'"><h2 class="text-xl font-bold">Team and event access</h2><p class="lp-subtitle">Team membership is managed per event through the authorized participant screen.</p><div class="lp-table-wrap mt-6"><table class="lp-table"><thead><tr><th>Event</th><th>Members</th><th></th></tr></thead><tbody><tr v-for="e in team" :key="e.id"><td>{{e.name}}</td><td>{{e.members_count}}</td><td><UiButton variant="secondary" :href="`/groups/${e.id}/members`">Manage</UiButton></td></tr></tbody></table></div></div><div v-else><h2 class="text-xl font-bold">Plan & billing</h2><p class="mt-3 text-sm text-slate-600">Current plan</p><p class="mt-1 text-3xl font-bold capitalize">{{user.plan}}</p><p class="mt-5 text-sm text-slate-600">Storage used: {{user.storage_used}} bytes</p><UiButton href="/pricing" class="mt-6">View available plans</UiButton></div></UiCard></div></div></AppShell></template>
